import{_ as r,a0 as n,w as i,s as m,ao as l,I as s,x as a,a1 as o,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"命令列下使用 Mop 監視股票價格 | LCTT x X-CMD","titleTemplate":false,"description":"命令列下使用 Mop 監視股票價格 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列下使用 Mop 監視股票價格 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列下使用 Mop 監視股票價格 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151012 How to Monitor Stock Prices from Ubuntu Command Line Using Mop","title":"命令列下使用 Mop 監視股票價格","tag":"201511","desc":""},"relativePath":"201511/20151012 How to Monitor Stock Prices from Ubuntu Command Line Using Mop.md","filePath":"[post].md"}'),d={name:"201511/20151012 How to Monitor Stock Prices from Ubuntu Command Line Using Mop.md"};function h(c,e,u,g,k,w){const t=n("Link");return i(),m("div",null,[e[13]||(e[13]=l(`<h1 id="命令列下使用-mop-監視股票價格" tabindex="-1">命令列下使用 Mop 監視股票價格 <a class="header-anchor" href="#命令列下使用-mop-監視股票價格" aria-label="Permalink to “命令列下使用 Mop 監視股票價格”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-featured-new.jpg" alt=""></p><p>有一份隱性收入通常很不錯，特別是當你可以輕鬆的協調業餘和全職工作。如果你的日常工作使用了聯網的電腦，交易股票就是一個獲取額外收入的很流行的選項。</p><p>但是目前只有很少的股票監視軟件可以運行在 linux 上，其中大多數還是基於圖形界面的。如果你是一個 Linux 專家，並且大量的工作時間是在沒有圖形界面的電腦上呢？你是不是就沒辦法了？不，還是有一些命令列下的股票追蹤工具，包括Mop，也就是本文要聊一聊的工具。</p><h3 id="mop" tabindex="-1">Mop <a class="header-anchor" href="#mop" aria-label="Permalink to “Mop”">​</a></h3><p>Mop，如上所述，是一個命令列下連續顯示和更新美股和獨立股票信息的工具。使用 GO 語言實現的，是 Michael Dvorkin 的智慧結晶。</p><h3 id="下載安裝" tabindex="-1">下載安裝 <a class="header-anchor" href="#下載安裝" aria-label="Permalink to “下載安裝”">​</a></h3><p>因為這個項目使用 GO 實現的，所以你要做的第一步是在你的計算機上安裝這種編程語言，下面就是在 Debian 系的系統，比如 Ubuntu 上安裝 GO 的步驟：</p><pre><code>sudo apt-get install golang
mkdir ~/workspace
echo &#39;export GOPATH=&quot;$HOME/workspace&quot;&#39; &gt;&gt; ~/.bashrc
source ~/.bashrc
</code></pre><p>GO 安裝好後的下一步是安裝 Mop 工具和配置環境，你要做的是運行下面的命令：</p><pre><code>sudo apt-get install git
go get github.com/michaeldv/mop
cd $GOPATH/src/github.com/michaeldv/mop
make install
export PATH=&quot;$PATH:$GOPATH/bin&quot;
</code></pre><p>完成之後就可以運行下面的命令執行 Mop：</p><pre><code>cmd
</code></pre><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h3><p>當你第一次運行 Mop 時，你會看到類似下面的輸出信息：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-first-run.jpg" alt=""></p><p>如你所見，這些輸出信息—— 週期性自動刷新 ——包含了主要幾個交易所和個股的信息。</p><h3 id="添加刪除股票" tabindex="-1">添加刪除股票 <a class="header-anchor" href="#添加刪除股票" aria-label="Permalink to “添加刪除股票”">​</a></h3><p>Mop 允許你輕鬆的從輸出列表上添加/刪除個股信息。要添加，你全部要做的是按“+”和輸入股票名稱。舉個例子，下圖就是添加 Facebook (FB) 到列表裏。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-add-stock.png" alt=""></p><p>我按下了“+”鍵，就出現了包含文本“Add tickers：”的一列，提示我添加股票名稱—— 我添加了 FB 然後按下回車。輸出列表更新了，我添加的新股票也出現在列表了：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-stock-added.png" alt=""></p><p>類似的，你可以使用“-”鍵和提供股票名稱刪除一個股票。</p><h4 id="根據價格分組" tabindex="-1">根據價格分組 <a class="header-anchor" href="#根據價格分組" aria-label="Permalink to “根據價格分組”">​</a></h4><p>還有一個把股票分組的辦法：依據他們的股價升跌，你所要做的就是按下“g”鍵。接下來，股票會分組顯示：升的在一起使用綠色字體顯示，而下跌的股票會黑色字體顯示。</p><p>如下所示：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-group-stocks-profit-loss.png" alt=""></p><h4 id="列排序" tabindex="-1">列排序 <a class="header-anchor" href="#列排序" aria-label="Permalink to “列排序”">​</a></h4><p>Mop 同時也允許你根據不同的列類型改變排序規則。這種用法需要你按下“o”（這個命令默認使用第一列的值來排序），然後使用左右鍵來選擇你要排序的列。完成之後按下回車對內容重新排序。</p><p>舉個例子，下面的截圖就是根據輸出內容的第一列、按照字母表排序之後的結果。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-change-order.png" alt=""></p><p><strong>注意</strong>: 為了更好的理解，和前面的截屏對比一下。</p><h4 id="其他選項" tabindex="-1">其他選項 <a class="header-anchor" href="#其他選項" aria-label="Permalink to “其他選項”">​</a></h4><p>其它的可用選項包括“p”：暫停市場和股票信息更新，“q”或者“esc” 來退出命令列程序，“?”顯示幫助頁。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-help.png" alt=""></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>Mop 是一個基礎的股票監控工具，並沒有提供太多的特性，只提供了它所聲稱的功能。很明顯，這個工具並不是為專業股票交易者提供的，而僅僅為你在只有命令列的機器上得體的提供了一個跟蹤股票信息的選擇。</p><hr>`,38)),s("p",null,[e[1]||(e[1]=a("via: ",-1)),o(t,{href:"https://www.maketecheasier.com/monitor-stock-prices-ubuntu-command-line/"},{default:p(()=>[...e[0]||(e[0]=[a("https://www.maketecheasier.com/monitor-stock-prices-ubuntu-command-line/",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=a("作者：",-1)),o(t,{href:"https://www.maketecheasier.com/author/himanshu/"},{default:p(()=>[...e[2]||(e[2]=[a("Himanshu Arora",-1)])]),_:1}),e[6]||(e[6]=a(" 譯者：",-1)),o(t,{href:"https://github.com/oska874"},{default:p(()=>[...e[3]||(e[3]=[a("oska874",-1)])]),_:1}),e[7]||(e[7]=a(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:p(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=a("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原創編譯，",-1)),o(t,{href:"https://linux.cn/"},{default:p(()=>[...e[9]||(e[9]=[a("Linux中國",-1)])]),_:1}),e[12]||(e[12]=a(" 榮譽推出",-1))])])}const T=r(d,[["render",h]]);export{M as __pageData,T as default};
